// A cache that holds weak references to values and tracks cleanup.
// When a cached value is garbage collected, its key is removed from
// the metadata map and the cleanup callback is invoked.
class WeakCache {
    #refs = new Map();        // key => WeakRef
    #meta = new Map();        // key => metadata
    #cleanedKeys = [];

