function createValidator(schema) {
    // schema: {fieldName: {type: 'string'|'number'|'boolean'|'array', required, min?, max?}}
    // Returns a Proxy that validates on set and throws on invalid assignments.
    const data = {};
    return new Proxy(data, {
        set(target, prop, value) {
            const rule = schema[prop];
            if (!rule) { target[prop] = value; return true; }
            switch (rule.type) {
                case 'string': {
                    if (typeof value !== 'string') throw new TypeError(`${prop} must be string`);
                    if (rule.min !== undefined && value.length < rule.min) throw new RangeError(`${prop} too short`);
                    if (rule.max !== undefined && value.length > rule.max) throw new RangeError(`${prop} too long`);
                    break;
