// filteredPipeline: async generator that filters+transforms with lifecycle logging

golden_completion:
async function* filteredPipeline(source, filterFn, transformFn) {
    pipeLog.push('open');
    try {
        for await (const item of source) {
            if (filterFn(item)) { pipeLog.push('yield:' + item); yield transformFn(item); }
        }
    } catch (err) { pipeLog.push('error:' + err.message); throw err; }
    finally { pipeLog.push('close'); }
}

