class Shape {
    #name;
    constructor(name) { this.#name = name; this._transforms = []; }
    get name() { return this.#name; }
    transform(t) { this._transforms.push(t); return this; }
    describe() { return `${this.#name}[${this._transforms.join(',')}]`; }
}

class Polygon extends Shape {
    #sides;
    constructor(name, sides) { super(name); this.#sides = sides; }
    get sides() { return this.#sides; }
    perimeter() { return this.#sides.reduce((s, l) => s + l, 0); }
    describe() { return `${super.describe()}(sides=${this.#sides.length})`; }
}

assert.strictEqual(new Polygon('tri', [3,4,5]).describe(), 'tri[](sides=3)');

