    get count() { return this.#count; }
    get sideLength() { return this.#len; }
    area() { return (this.#count * this.#len ** 2) / (4 * Math.tan(Math.PI / this.#count)); }
    describe() { return `${super.describe()}(regular,len=${this.#len})`; }
}

