function fetchFromPrimary(id) {
    return new Promise((resolve, reject) => {
        setTimeout(() => reject(new Error('primary_down')), 10);
    });
}

function fetchFromSecondary(id) {
    return new Promise((resolve, reject) => {
        setTimeout(() => reject(new Error('secondary_timeout')), 20);
    });
}

function fetchFromCache(id) {
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            if (id > 0) resolve({ id, source: 'cache', data: 'cached_' + id });
            else reject(new Error('cache_miss'));
        }, 5);
    });
}

async function fetchWithFallback(id) {

golden_completion:
    try {
        const result = await Promise.any([
            fetchFromPrimary(id),
            fetchFromSecondary(id),
            fetchFromCache(id)
        ]);
        return { success: true, ...result };
    } catch (err) {
        if (err instanceof AggregateError) {
            const reasons = err.errors.map(e => e.message);
            return {
                success: false,
                errors: reasons,
                errorCount: reasons.length
            };
        }
        throw err;
    }
}

